#include <stdio.h>

#define NODES 3

typedef struct { int counts[NODES]; } GCounter;

void g_init(GCounter *c) { for (int i = 0; i < NODES; i++) c->counts[i] = 0; }
void g_inc(GCounter *c, int node) { c->counts[node]++; }
int g_val(GCounter *c) { int sum=0; for(int i=0;i<NODES;i++) sum+=c->counts[i]; return sum; }
void g_merge(GCounter *a, GCounter *b) {
    for (int i = 0; i < NODES; i++)
        if (b->counts[i] > a->counts[i]) a->counts[i] = b->counts[i];
}

int main() {
    GCounter a, b;
    g_init(&a); g_init(&b);
    g_inc(&a, 0); g_inc(&a, 0);
    g_inc(&b, 1); g_inc(&b, 1); g_inc(&b, 1);
    printf("A: %d, B: %d\n", g_val(&a), g_val(&b));
    g_merge(&a, &b);
    printf("Merged: %d\n", g_val(&a));
    return 0;
}
